<script setup lang="ts">
import type { SubmissionPayload } from "~/composables/useSubmissionWizard";
const props = defineProps<{ media: SubmissionPayload["media"]; description: string; error?: string }>();
const emit = defineEmits<{ "update:media": [value: SubmissionPayload["media"]]; "update:description": [value: string] }>();
function selectFiles(event: Event) { const files = [...((event.target as HTMLInputElement).files ?? [])].slice(0, 10 - props.media.length); emit("update:media", [...props.media, ...files.map((file) => ({ clientId: crypto.randomUUID(), kind: file.type.startsWith("video/") ? "video" as const : "image" as const, name: file.name, size: file.size, contentType: file.type, status: "staged" as const }))]); }
</script>
<template><section><h2>تصویر، ویدیو و توضیحات</h2><p class="submission-hint">تا ۱۰ فایل انتخاب کنید. ارسال امن فایل‌ها در مرحله بعدی توسعه فعال می‌شود.</p><label class="media-drop"><input type="file" accept="image/jpeg,image/png,image/webp,video/mp4" multiple @change="selectFiles"><strong>افزودن تصویر یا ویدیو</strong><span>JPG، PNG، WebP یا MP4</span></label><ul class="staged-media"><li v-for="item in media" :key="item.clientId"><span>{{ item.kind === 'image' ? 'تصویر' : 'ویدیو' }}</span><strong>{{ item.name }}</strong><button type="button" @click="emit('update:media', media.filter(file => file.clientId !== item.clientId))">حذف</button></li></ul><label class="submission-description"><span>توضیحات *</span><textarea :value="description" rows="7" maxlength="4000" placeholder="ویژگی‌ها و شرایط معامله را شفاف بنویسید" @input="emit('update:description', ($event.target as HTMLTextAreaElement).value)"></textarea><small v-if="error" class="field-error">{{ error }}</small></label></section></template>
